def suite_results(output):
    summaries=re.findall(r'test result: (ok|FAILED)\. (\d+) passed; (\d+) failed;',output)
    assert len(summaries)==2 and 'could not compile' not in output,output[-3000:]
    for summary,count in zip(summaries,[58,80]):
        assert int(summary[1])+int(summary[2])==count,summary
    return [0 if summary[0]=='ok' else 101 for summary in summaries]

def run(name,cmd,expected=0,timeout=180,env=None):
    p=subprocess.run(cmd,cwd=B,env=env or ENV,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=timeout)
    p.stdout=portable(p.stdout)
    (B/'evidence/gen'/f'{name}.txt').write_text(H+'command = '+portable(repr(cmd))+'\n'+p.stdout+f'\nexit_code = {p.returncode}\n')
    if expected is not None and p.returncode!=expected:raise RuntimeError(name+' unexpected exit '+str(p.returncode)+'\n'+p.stdout[-4000:])
    return p

def build(name='schemata-build',separate=None,real=False):
    from schemata import sources
    manifest=B/'net-copy/Cargo.toml'; target=B/'target/schemata'
    if separate:
        folder=B/'target/separate'/separate/'package'
        (folder/'src/net').mkdir(parents=True,exist_ok=True)
        for file,source in sources(separate).items():(folder/'src/net'/file).write_text(source)
        for file in ['Cargo.toml','Cargo.lock','src/lib.rs']:
            (folder/file).write_bytes((B/'net-copy'/file).read_bytes())
        import shutil
        shutil.copytree(B/'net-copy/tests',folder/'tests',dirs_exist_ok=True)
        manifest=folder/'Cargo.toml'; target=folder.parent/'build'
    cmd=['cargo','+1.99.0','test','--offline','--locked','--manifest-path',str(manifest),'--target-dir',str(target),'--no-run','--message-format=json']
    if real:cmd+=['--features','real-std','--test','proposed']
    else:cmd+=['--test','upstream','--test','upstream_docs','--test','proposed']
    output=run(name,cmd,timeout=300).stdout
    artifacts={}
    for line in output.splitlines():
        try:row=json.loads(line)
        except ValueError:continue
        if row.get('reason')=='compiler-artifact' and row.get('executable'):
            artifacts[row['target']['name']]=B/row['executable']
    assert set(artifacts)==({'proposed'} if real else {'proposed','upstream','upstream_docs'}),artifacts
    if name=='schemata-build':
        receipt={'provenance':H.strip('# \n'),'executables':{key:str(value.relative_to(B)) for key,value in artifacts.items()}}
        (B/'evidence/gen/schemata-artifacts.json').write_text(json.dumps(receipt,indent=2)+'\n')
    return artifacts

def execute(name,artifacts,id=0,test=None):
    env={**ENV,'NET_MUTANT':str(id)}
    commands=[];outputs=[];exits=[]
    for suite in (['upstream','upstream_docs'] if test is None else ['proposed']):
        cmd=[str(artifacts[suite])]
        if test:cmd+=[test,'--exact'] if test!='all' else []
        cmd+=['--test-threads=1']
        p=subprocess.run(cmd,cwd=B,env=env,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=180)
        assert p.returncode in [0,101],(name,p.returncode,p.stdout)
        commands.append(cmd);outputs.append(p.stdout);exits.append(p.returncode)
    output=portable('\n'.join(outputs)); code=max(exits)
    (B/'evidence/gen'/f'{name}.txt').write_text(H+f'NET_MUTANT = {id}\ncommand = '+portable(repr(commands))+'\n'+output+f'\nexit_code = {code}\n')
    return code,output

def outcomes(output):
    pairs=re.findall(r'^test (\S+) \.\.\. (ok|FAILED)$',output,re.M)
    assert pairs and len(dict(pairs))==len(pairs),'missing or duplicate per-test results'
    return dict(pairs)

def compare(id,suite,output):
    reference=B/'evidence/run3'/f'{id}-{suite}.txt'
    old=outcomes(reference.read_text());new=outcomes(output)
    delta={name:{'run3':old.get(name),'schemata':new.get(name)} for name in sorted(old.keys()|new.keys()) if old.get(name)!=new.get(name)}
    return {'suite':suite,'tests':len(new),'equal':not delta,'differences':delta}

def mutants(only=None):
    from schemata import SEPARATE,original_sources,write
    started=time.monotonic();write()
    rows=json.loads((B/'mutants.json').read_text())['mutants']
    artifacts=build(); builds=1
    exit,output=execute('upstream-baseline',artifacts)
    assert exit==0 and suite_results(output)==[0,0]
    assert execute('proposed-copy',artifacts,test='all')[0]==0
    results=[];comparisons=[]
    for m in rows:
        if only and m['id']!=only:continue
        id=int(m['id'][1:]);separate=id in SEPARATE
        base_exit,base_output=execute(m['id']+'-baseline',artifacts,test=m['test_name'])
        assert base_exit==0 and len(outcomes(base_output))==1
        variant=build(m['id']+'-build',m['id']) if separate else artifacts
        builds+=int(separate)
        active=0 if separate else id
        upstream_exit,upstream_output=execute(m['id']+'-upstream',variant,active)
        files_exit,docs_exit=suite_results(upstream_output)
        proposed_exit,proposed_output=execute(m['id']+'-proposed',variant,active,m['test_name'])
        assert proposed_exit==101 and 'test result: FAILED. 0 passed; 1 failed;' in proposed_output,m['id']
        result=dict(id=m['id'],item=m['item'],missing=upstream_exit==0,equivalent=False,upstream_exit=upstream_exit,upstream_files_exit=files_exit,upstream_docs_exit=docs_exit,proposed_exit=proposed_exit)
        results.append(result)
        checks=[compare(m['id'],suite,output) for suite,output in [('baseline',base_output),('upstream',upstream_output),('proposed',proposed_output)]]
        comparisons.append(dict(id=m['id'],mode='separate build' if separate else 'runtime',checks=checks,equal=all(c['equal'] for c in checks)))
        original=original_sources()[m['file']];mutated=original.replace(m['old'],m['new'])
        assert original!=mutated,m['id']
        (B/'evidence/gen'/f'{m["id"]}.patch').write_text(H+''.join(difflib.unified_diff(original.splitlines(True),mutated.splitlines(True),fromfile='a/net-copy/src/net/'+m['file'],tofile='b/net-copy/src/net/'+m['file'])))
        print(m['id']+(' MISSING' if result['missing'] else ' detected')+(' comparison MATCH' if comparisons[-1]['equal'] else ' comparison DIFFERENCE'),flush=True)
    timing={'provenance':H.strip('# \n'),'wall_seconds':round(time.monotonic()-started,3),'build_count':builds,'shared_schemata_builds':1,'separate_mutant_builds':builds-1,'runtime_mutants':sum(r['mode']=='runtime' for r in comparisons),'scope':'Upstream baseline, all copy proposed baselines, 100 upstream mutant suites and individual green/red proposed cases. One shared build plus isolated const builds. Real-std baseline measured separately.'}
    if not only:
        reference=json.loads((B/'evidence/run3/mutation-results.json').read_text())['results']
        (B/'evidence/gen/mutation-results.json').write_text(json.dumps({'provenance':H.strip('# \n'),'results':results},indent=2)+'\n')
        (B/'evidence/gen/schemata-comparison.json').write_text(json.dumps({'provenance':H.strip('# \n'),'rows':comparisons},indent=2)+'\n')
        (B/'evidence/gen/timing-after.json').write_text(json.dumps(timing,indent=2)+'\n')
        document(comparisons,timing)
        assert results==reference and all(r['equal'] for r in comparisons),'run-3 comparison differs; SCHEMATA.md records the finding'
    real=build('proposed-real-std-build',real=True)
    assert execute('proposed-real-std',real,test='all')[0]==0
    print('MUTANTS PASS: each proposed assertion observed runtime red; run-3 results retained',flush=True)

def document(rows,timing):
    from schemata import SEPARATE
    mutants=json.loads((B/'mutants.json').read_text())['mutants']
    before=json.loads((B/'evidence/gen/timing-before.json').read_text())
    text='<!-- '+H.strip('# \n')+' -->\n# Mutant schemata\n\n'
    text+=f'{100-len(SEPARATE)} mutants use one shared build. `mutant_active(id)` caches `NET_MUTANT` in a OnceLock. Absent or 0 selects the original code. Each test process gets a fresh switch. Mutant ids remain stable. M095 now preserves the payload and checks the full translated prefix; its run-3 reference used the earlier constant-output change. Outcome agreement below compares test names and pass/fail results, not identical mutation semantics. Function bodies are generated from the pinned copy; branches preserve every occurrence of an edit, including both formatter padding paths for M100.\n\n'
    text+='The remaining mutants retain their own build because stable Rust cannot read an environment variable during const evaluation. The upstream const tests and their declarations remain unchanged. Only guarded methods and their runtime callers lose `const` in the copy; this does not test those methods as const. Each separate build has an isolated crate and target under target/separate; it leaves the shared copy unchanged. Published sources remain read-only.\n\n'
    text+='| Mutant | API item | Reason for separate build |\n| --- | --- | --- |\n'
    for m in mutants:
        if int(m['id'][1:]) in SEPARATE:
            reason='Associated constant: its value is fixed at compile time.' if int(m['id'][1:])<=7 else 'Used directly or transitively by the unchanged upstream const tests or const address fixtures.'
            text+=f'| {m["id"]} | `{m.get("behaviour",m["item"])}` | {reason} |\n'
    text+='\n| Measurement | Before | After |\n| --- | --- | --- |\n'
    text+=f'| Mutation configurations compiled | 100 | {timing["separate_mutant_builds"]} separate + 1 shared |\n'
    text+=f'| Cargo invocations that compiled net-copy | {before["cargo_compilation_invocations"]} | {timing["build_count"]} no-run build invocations |\n'
    text+=f'| Mutation runner wall seconds | {before["wall_seconds"]} | {timing["wall_seconds"]} |\n'
    text+='\nBefore is a measured replay of the legacy runner with the existing incremental target and warm cache, including its real-std baseline. After includes the shared upstream/copy baselines and identical mutant suites; the real-std baseline uses one additional build outside the mutation timer. These are local wall times, not a cross-machine performance guarantee. Before includes repeated restoration and separate upstream/proposed Cargo compilations. Full package wall time is recorded in evidence/gen/package-timing.json. Receipts: [before](evidence/gen/timing-before.json), [after](evidence/gen/timing-after.json).\n\n'
    text+='Id 0 passes all 138 upstream tests and all 100 proposed tests. The real-std baseline also passes all 100 proposed tests. [Run-3 reference receipts](evidence/run3/README.md) retain original per-test outcomes with paths normalized. The comparison below checks exact names and pass/fail results for all 138 upstream tests and the selected green/red proposed assertion, including separate-build mutants. [Machine-readable comparisons](evidence/gen/schemata-comparison.json) record every difference.\n\n'
    differences=[r for r in rows if not r['equal']]
    text+=('No per-test differences were found. The 19 missing cases (12 behavioural cases covering 7 distinct behaviours, including six whitespace cases for one rule, and 7 optional representation snapshots) and 143 weighted claims remain unchanged.\n\n' if not differences else 'Finding: per-test differences were found; see the explicit deltas below and in the JSON receipt.\n\n')
    text+='| Mutant | Mode | Upstream names/outcomes | Proposed green/red | Run-3 match |\n| --- | --- | --- | --- | --- |\n'
    for row in rows:
        checks={c['suite']:c for c in row['checks']}
        text+=f'| [{row["id"]}](evidence/gen/{row["id"]}-upstream.txt) | {row["mode"]} | {checks["upstream"]["tests"]} checked | 1 / 1 checked | '+('MATCH' if row['equal'] else 'DIFFERENCE')+' |\n'
    for row in differences:text+='\n```json\n'+json.dumps(row,indent=2)+'\n```\n'
    (B/'SCHEMATA.md').write_text(text)

